/**
 * Embed the agent skill (plugin/skills/hedgesync) in the CLI, so `hedgesync agent
 * install` always installs the copy that matches the binary.
 *
 * Writes src/cli/skill.generated.ts. Run with `bun run gen:skill`; a unit
 * test fails when the generated file is stale.
 */
import { readdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { join, relative, sep } from 'node:path';

const ROOT = join(import.meta.dir, '..');
export const SKILL = join(ROOT, 'plugin/skills/hedgesync');
export const GENERATED = join(ROOT, 'src/cli/skill.generated.ts');

function walk(dir: string): string[] {
  return readdirSync(dir).sort().flatMap((name) => {
    const path = join(dir, name);
    return statSync(path).isDirectory() ? walk(path) : [path];
  });
}

export function renderSkillModule(): string {
  const entries = walk(SKILL).map((path) => {
    const rel = relative(SKILL, path).split(sep).join('/');
    return `  ${JSON.stringify(rel)}: ${JSON.stringify(readFileSync(path, 'utf8'))},`;
  });
  return `// Generated by scripts/gen-skill.ts from plugin/skills/hedgesync. Do not edit.
// Regenerate with: bun run gen:skill

/** The agent skill's files, by path relative to the skill directory. */
export const SKILL_FILES: Record<string, string> = {
${entries.join('\n')}
};
`;
}

if (import.meta.main) {
  writeFileSync(GENERATED, renderSkillModule());
  console.log(`wrote ${relative(ROOT, GENERATED)}`);
}
